  'use strict';
  const form = document.getElementById('estimate-form');
  const email = document.getElementById('email');
  const description = document.getElementById('description');
  const radios = Array.from(form.querySelectorAll('input[name="piece"]'));
  const confirmation = document.getElementById('confirmation');
  const errorSummary = document.getElementById('error-summary');
  let attempted = false;

  function validate() {
    const selected = radios.find(radio => radio.checked);
    const states = [
      { id: 'piece', controls: radios, valid: Boolean(selected) },
      { id: 'email', controls: [email], valid: Boolean(email.value.trim()) && email.validity.valid },
      { id: 'description', controls: [description], valid: Boolean(description.value.trim()) && description.value.length <= 3000 }
    ];
    states.forEach(state => {
      document.getElementById(state.id + '-error').hidden = state.valid;
      state.controls.forEach(control => control.setAttribute('aria-invalid', String(!state.valid)));
    });
    const invalid = states.filter(state => !state.valid);
    errorSummary.hidden = invalid.length === 0;
    errorSummary.textContent = invalid.length ? 'Check the marked fields to finish your request.' : '';
    return { selected, invalid };
  }

  form.addEventListener('submit', event => {
    event.preventDefault();
    attempted = true;
    email.value = email.value.trim();
    const { selected, invalid } = validate();
    if (invalid.length) {
      invalid[0].controls[0].focus();
      return;
    }
    document.getElementById('summary-piece').textContent = selected.value;
    document.getElementById('summary-email').textContent = email.value;
    document.getElementById('summary-description').textContent = description.value.trim();
    form.hidden = true;
    confirmation.hidden = false;
    document.getElementById('confirmation-title').focus();
  });
  form.addEventListener('input', () => { if (attempted) validate(); });
  document.getElementById('edit-request').addEventListener('click', () => {
    confirmation.hidden = true;
    form.hidden = false;
    (radios.find(radio => radio.checked) || radios[0]).focus();
  });
  document.getElementById('submit-request').disabled = false;

